! ============================================================
! VML VGA 图形扩展库 — Fortran
!
! 使用示例:
!   call asm("SYSCALL 60")    ! GetConfig — 获取 VGA 寄存器地址
!   call asm("SYSCALL 200")   ! DebugScreenshot — 保存帧缓冲为 BMP
!   call asm("SYSCALL 201")   ! PutImage — 像素数据写入帧缓冲
!   call asm("SYSCALL 202")   ! GetImage — 从帧缓冲读取像素
!   call asm("SYSCALL 203")   ! Viewport — 设置图形裁剪区域
!
! VGA 通过 MMIO 地址访问:
!   VGA_MODE:   0x6FF0  (GetConfig 码=6)
!   帧缓冲:    0xA0000 (图形模式, GetConfig 码=1)
!   文本缓冲:  0xB8000 (文本模式, GetConfig 码=0)
!   光标行:    0x6FF4  (GetConfig 码=2)
!   光标列:    0x6FF8  (GetConfig 码=3)
!   前景色:    0x6FFC  (GetConfig 码=4)
!   背景色:    0x6FFD  (GetConfig 码=5)
! ============================================================

! ============================================================
! SYSCALL 60 — GetConfig (图形相关查询码)
! 获取 VGA 配置地址
! 参数: R0 = 查询码
! 返回: R0 = 地址或值
!
! 查询码:
!   0 = VGA_FRAMEBUFFER    — 文本模式帧缓冲基址 (0xB8000)
!   1 = VGA_GFX_FB         — 图形模式帧缓冲基址 (0xA0000)
!   2 = CURSOR_ROW         — 光标行地址 (0x6FF4)
!   3 = CURSOR_COL         — 光标列地址 (0x6FF8)
!   4 = FG_COLOR           — 前景色地址 (0x6FFC)
!   5 = BG_COLOR           — 背景色地址 (0x6FFD)
!   6 = VGA_MODE           — VGA 模式寄存器地址 (0x6FF0)
!   7 = MEMORY_SIZE        — 总内存字节数
!   8 = DISPLAY_WIDTH      — 显示宽度
!   9 = DISPLAY_HEIGHT     — 显示高度
!
! Fortran 使用示例:
!   ! 获取图形帧缓冲地址
!   call asm("STORE 1, R0")
!   call asm("SYSCALL 60")
!   ! 返回: R0 = 0xA0000
! ============================================================

! ============================================================
! SYSCALL 200 — DebugScreenshot
! 立即保存当前 VGA 帧缓冲为 BMP 文件
! 参数: 无
! 返回: R0 = 0 成功, <0 失败
!
! 输出文件: debug_shot_{序号}.bmp
! 自动从 MMIO 寄存器读取当前模式和分辨率
!
! Fortran 使用示例:
!   call asm("SYSCALL 200")
!   ! 当前帧缓冲被保存为 debug_shot_0001.bmp
! ============================================================

! ============================================================
! SYSCALL 201 — PutImage
! 将像素数据从内存写入 VGA 帧缓冲
! 参数:
!   R0 = 目标 X 坐标
!   R1 = 目标 Y 坐标
!   R2 = 宽度 (像素)
!   R3 = 高度 (像素)
!   R4 = 像素数据地址 (RGB 24-bit, 行优先)
! 返回: R0 = 0 成功, -300 = VGA 设备未找到
!
! Fortran 使用示例:
!   ! 在 (10, 20) 处绘制 32x32 图像
!   ! R0=10, R1=20, R2=32, R3=32, R4=像素数据地址
!   call asm("SYSCALL 201")
! ============================================================

! ============================================================
! SYSCALL 202 — GetImage
! 从 VGA 帧缓冲读取像素数据到内存
! 参数:
!   R0 = 源 X 坐标
!   R1 = 源 Y 坐标
!   R2 = 宽度 (像素)
!   R3 = 高度 (像素)
!   R4 = 目标缓冲区地址
! 返回: R0 = 0 成功, -300 = VGA 设备未找到
!
! Fortran 使用示例:
!   ! 从 (0, 0) 读取 64x48 区域
!   ! R0=0, R1=0, R2=64, R3=48, R4=缓冲区地址
!   call asm("SYSCALL 202")
! ============================================================

! ============================================================
! SYSCALL 203 — Viewport
! 设置图形裁剪区域
! 参数:
!   R0 = 左上角 X
!   R1 = 左上角 Y
!   R2 = 右下角 X
!   R3 = 右下角 Y
! 返回: R0 = 0 成功, <0 不支持
!
! 注意: 当前为 stub
!
! Fortran 使用示例:
!   ! 设置裁剪区域 (0,0) 到 (320,200)
!   ! R0=0, R1=0, R2=320, R3=200
!   call asm("SYSCALL 203")
! ============================================================

! ============================================================
! VGA 设备控制命令 (SYSCALL 104 DeviceControl):
!   命令=0: 获取设备信息
!   命令=1: 清屏
!   命令=2: 设置像素
!   命令=3: 绘制字符
!   命令=4: 绘制字符串
!   命令=5: 设置模式
!   命令=6: 获取帧缓冲
!
! 使用:
!   1. SYSCALL 100 (DeviceOpen, "vga")  获取设备句柄
!   2. SYSCALL 104 (DeviceControl)      执行 VGA 命令
!   3. SYSCALL 101 (DeviceClose)        关闭设备
! ============================================================

! ============================================================
! VML 汇编共享库 CALL 目标 (VGA):
!   CALL vga_clear     — 清屏
!   CALL vga_print     — VGA 输出字符串
!   CALL putchar       — 输出字符 (控制台)
! ============================================================
